import 'package:flutter/material.dart';\nimport 'package:intl/intl.dart';\nimport 'package:path_provider/path_provider.dart';\nimport 'dart:io';\n\nimport '../../widgets/loading_state_view.dart';\nimport '../../widgets/section_header.dart';\nimport 'pdf_file_manager.dart';\n\nclass PdfFilesManagerScreen extends StatefulWidget {\n  const PdfFilesManagerScreen({super.key});\n\n  @override\n  State<PdfFilesManagerScreen> createState() => _PdfFilesManagerScreenState();\n}\n\nclass _PdfFilesManagerScreenState extends State<PdfFilesManagerScreen> {\n  List<FileInfo> _allFiles = [];\n  List<FileInfo> _filteredFiles = [];\n  bool _isLoading = true;\n  PdfTemplateType? _selectedTemplate;\n  DateTime? _startDate;\n  DateTime? _endDate;\n  String _searchQuery = '';\n\n  @override\n  void initState() {\n    super.initState();\n    _loadFiles();\n  }\n\n  Future<void> _loadFiles() async {\n    setState(() => _isLoading = true);\n    try {\n      final files = await PdfFileManager.getAllPdfFiles(\n        startDate: _startDate,\n        endDate: _endDate,\n      );\n      setState(() {\n        _allFiles = files;\n        _applyFilters();\n        _isLoading = false;\n      });\n    } catch (e) {\n      setState(() => _isLoading = false);\n      if (mounted) {\n        ScaffoldMessenger.of(context).showSnackBar(\n          SnackBar(content: Text('خطأ في تحميل الملفات: $e')),\n        );\n      }\n    }\n  }\n\n  void _applyFilters() {\n    _filteredFiles = _allFiles.where((file) {\n      // فلتر نوع القالب\n      if (_selectedTemplate != null && file.templateType != _selectedTemplate) {\n        return false;\n      }\n      \n      // فلتر البحث\n      if (_searchQuery.isNotEmpty &&\n          !file.displayName.toLowerCase().contains(_searchQuery.toLowerCase())) {\n        return false;\n      }\n      \n      return true;\n    }).toList();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('إدارة ملفات PDF'),\n        actions: [\n          IconButton(\n            onPressed: _showCleanupDialog,\n            icon: const Icon(Icons.cleaning_services),\n            tooltip: 'تنظيف الملفات',\n          ),\n          IconButton(\n            onPressed: _showStorageInfo,\n            icon: const Icon(Icons.info),\n            tooltip: 'معلومات التخزين',\n          ),\n        ],\n      ),\n      body: Column(\n        children: [\n          // شريط البحث والفلاتر\n          _buildFilterBar(),\n          \n          // إحصائيات سريعة\n          _buildQuickStats(),\n          \n          // قائمة الملفات\n          Expanded(\n            child: _isLoading\n                ? const LoadingStateView()\n                : _filteredFiles.isEmpty\n                    ? _buildEmptyState()\n                    : _buildFilesList(),\n          ),\n        ],\n      ),\n      floatingActionButton: FloatingActionButton(\n        onPressed: _loadFiles,\n        child: const Icon(Icons.refresh),\n      ),\n    );\n  }\n\n  Widget _buildFilterBar() {\n    return Container(\n      padding: const EdgeInsets.all(16),\n      decoration: BoxDecoration(\n        color: Theme.of(context).colorScheme.surfaceVariant,\n        borderRadius: const BorderRadius.only(\n          bottomLeft: Radius.circular(16),\n          bottomRight: Radius.circular(16),\n        ),\n      ),\n      child: Column(\n        children: [\n          // شريط البحث\n          TextField(\n            decoration: const InputDecoration(\n              labelText: 'البحث في الملفات',\n              prefixIcon: Icon(Icons.search),\n              border: OutlineInputBorder(),\n            ),\n            onChanged: (value) {\n              setState(() {\n                _searchQuery = value;\n                _applyFilters();\n              });\n            },\n          ),\n          \n          const SizedBox(height: 16),\n          \n          // فلاتر\n          Row(\n            children: [\n              // فلتر نوع القالب\n              Expanded(\n                child: DropdownButtonFormField<PdfTemplateType?>(\n                  value: _selectedTemplate,\n                  decoration: const InputDecoration(\n                    labelText: 'نوع القالب',\n                    border: OutlineInputBorder(),\n                  ),\n                  items: [\n                    const DropdownMenuItem<PdfTemplateType?>(\n                      value: null,\n                      child: Text('جميع الأنواع'),\n                    ),\n                    ...PdfTemplateType.values.map((type) {\n                      return DropdownMenuItem<PdfTemplateType?>(\n                        value: type,\n                        child: Text(type.displayName),\n                      );\n                    }).toList(),\n                  ],\n                  onChanged: (value) {\n                    setState(() {\n                      _selectedTemplate = value;\n                      _applyFilters();\n                    });\n                  },\n                ),\n              ),\n              \n              const SizedBox(width: 16),\n              \n              // فلتر التاريخ\n              Expanded(\n                child: Row(\n                  children: [\n                    Expanded(\n                      child: OutlinedButton.icon(\n                        onPressed: _selectStartDate,\n                        icon: const Icon(Icons.calendar_today),\n                        label: Text(\n                          _startDate != null\n                              ? DateFormat('yyyy/MM/dd').format(_startDate!)\n                              : 'من تاريخ',\n                        ),\n                      ),\n                    ),\n                    const SizedBox(width: 8),\n                    Expanded(\n                      child: OutlinedButton.icon(\n                        onPressed: _selectEndDate,\n                        icon: const Icon(Icons.calendar_today),\n                        label: Text(\n                          _endDate != null\n                              ? DateFormat('yyyy/MM/dd').format(_endDate!)\n                              : 'إلى تاريخ',\n                        ),\n                      ),\n                    ),\n                  ],\n                ),\n              ),\n            ],\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildQuickStats() {\n    final totalSize = _filteredFiles.fold<int>(\n      0,\n      (sum, file) => sum + file.size,\n    );\n    \n    final typeGroups = <PdfTemplateType, int>{};\n    for (final file in _filteredFiles) {\n      typeGroups[file.templateType] = (typeGroups[file.templateType] ?? 0) + 1;\n    }\n\n    return Container(\n      padding: const EdgeInsets.all(16),\n      child: Row(\n        children: [\n          Expanded(\n            child: _StatCard(\n              title: 'إجمالي الملفات',\n              value: '${_filteredFiles.length}',\n              icon: Icons.folder,\n              color: Colors.blue,\n            ),\n          ),\n          const SizedBox(width: 12),\n          Expanded(\n            child: _StatCard(\n              title: 'الحجم الإجمالي',\n              value: _formatFileSize(totalSize),\n              icon: Icons.storage,\n              color: Colors.green,\n            ),\n          ),\n          const SizedBox(width: 12),\n          Expanded(\n            child: _StatCard(\n              title: 'الأنواع',\n              value: '${typeGroups.length}',\n              icon: Icons.category,\n              color: Colors.orange,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildFilesList() {\n    // تجميع الملفات حسب التاريخ\n    final groupedFiles = <String, List<FileInfo>>{};\n    for (final file in _filteredFiles) {\n      final dateKey = DateFormat('yyyy-MM-dd').format(file.createdDate);\n      if (!groupedFiles.containsKey(dateKey)) {\n        groupedFiles[dateKey] = [];\n      }\n      groupedFiles[dateKey]!.add(file);\n    }\n\n    final sortedKeys = groupedFiles.keys.toList()\n      ..sort((a, b) => b.compareTo(a)); // الأحدث أولاً\n\n    return ListView.builder(\n      padding: const EdgeInsets.all(16),\n      itemCount: sortedKeys.length,\n      itemBuilder: (context, index) {\n        final dateKey = sortedKeys[index];\n        final files = groupedFiles[dateKey]!;\n        final date = DateTime.parse(dateKey);\n        \n        return Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            // عنوان التاريخ\n            Padding(\n              padding: const EdgeInsets.symmetric(vertical: 12),\n              child: Row(\n                children: [\n                  Icon(\n                    Icons.calendar_today,\n                    size: 16,\n                    color: Theme.of(context).colorScheme.primary,\n                  ),\n                  const SizedBox(width: 8),\n                  Text(\n                    DateFormat('EEEE، yyyy/MM/dd', 'ar').format(date),\n                    style: Theme.of(context).textTheme.titleMedium?.copyWith(\n                      color: Theme.of(context).colorScheme.primary,\n                      fontWeight: FontWeight.bold,\n                    ),\n                  ),\n                  const SizedBox(width: 8),\n                  Text(\n                    '(${files.length} ملف)',\n                    style: Theme.of(context).textTheme.bodyMedium?.copyWith(\n                      color: Colors.grey,\n                    ),\n                  ),\n                ],\n              ),\n            ),\n            \n            // قائمة الملفات لهذا التاريخ\n            ...files.map((file) => _buildFileCard(file)),\n            \n            if (index < sortedKeys.length - 1)\n              const Divider(height: 24),\n          ],\n        );\n      },\n    );\n  }\n\n  Widget _buildFileCard(FileInfo file) {\n    return Card(\n      margin: const EdgeInsets.only(bottom: 8),\n      child: ListTile(\n        leading: CircleAvatar(\n          backgroundColor: _getTemplateColor(file.templateType),\n          child: Icon(\n            _getTemplateIcon(file.templateType),\n            color: Colors.white,\n            size: 20,\n          ),\n        ),\n        title: Text(\n          file.displayName,\n          style: const TextStyle(fontWeight: FontWeight.bold),\n        ),\n        subtitle: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            Text('النوع: ${file.templateType.displayName}'),\n            Text('الحجم: ${file.formattedSize}'),\n            Text('التاريخ: ${file.formattedDate}'),\n          ],\n        ),\n        trailing: PopupMenuButton<String>(\n          onSelected: (action) => _handleFileAction(action, file),\n          itemBuilder: (context) => [\n            const PopupMenuItem(\n              value: 'open',\n              child: ListTile(\n                leading: Icon(Icons.open_in_new),\n                title: Text('فتح'),\n              ),\n            ),\n            const PopupMenuItem(\n              value: 'share',\n              child: ListTile(\n                leading: Icon(Icons.share),\n                title: Text('مشاركة'),\n              ),\n            ),\n            const PopupMenuItem(\n              value: 'rename',\n              child: ListTile(\n                leading: Icon(Icons.edit),\n                title: Text('إعادة تسمية'),\n              ),\n            ),\n            const PopupMenuItem(\n              value: 'delete',\n              child: ListTile(\n                leading: Icon(Icons.delete, color: Colors.red),\n                title: Text('حذف', style: TextStyle(color: Colors.red)),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildEmptyState() {\n    return Center(\n      child: Column(\n        mainAxisAlignment: MainAxisAlignment.center,\n        children: [\n          Icon(\n            Icons.folder_open,\n            size: 64,\n            color: Colors.grey[400],\n          ),\n          const SizedBox(height: 16),\n          Text(\n            'لا توجد ملفات PDF',\n            style: Theme.of(context).textTheme.titleMedium?.copyWith(\n              color: Colors.grey[600],\n            ),\n          ),\n          const SizedBox(height: 8),\n          Text(\n            'قم بإنشاء بطاقات أو تقارير لتظهر هنا',\n            style: Theme.of(context).textTheme.bodyMedium?.copyWith(\n              color: Colors.grey[500],\n            ),\n          ),\n          const SizedBox(height: 24),\n          FilledButton.icon(\n            onPressed: () => Navigator.pop(context),\n            icon: const Icon(Icons.add),\n            label: const Text('إنشاء ملف جديد'),\n          ),\n        ],\n      ),\n    );\n  }\n\n  // دوال مساعدة\n  Color _getTemplateColor(PdfTemplateType type) {\n    switch (type) {\n      case PdfTemplateType.cards:\n        return Colors.blue;\n      case PdfTemplateType.reports:\n        return Colors.green;\n      case PdfTemplateType.invoices:\n        return Colors.orange;\n      case PdfTemplateType.users:\n        return Colors.purple;\n      case PdfTemplateType.backup:\n        return Colors.teal;\n    }\n  }\n\n  IconData _getTemplateIcon(PdfTemplateType type) {\n    switch (type) {\n      case PdfTemplateType.cards:\n        return Icons.credit_card;\n      case PdfTemplateType.reports:\n        return Icons.analytics;\n      case PdfTemplateType.invoices:\n        return Icons.receipt;\n      case PdfTemplateType.users:\n        return Icons.people;\n      case PdfTemplateType.backup:\n        return Icons.backup;\n    }\n  }\n\n  String _formatFileSize(int bytes) {\n    if (bytes < 1024) {\n      return '$bytes B';\n    } else if (bytes < 1024 * 1024) {\n      return '${(bytes / 1024).toStringAsFixed(1)} KB';\n    } else {\n      return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MB';\n    }\n  }\n\n  // دوال الأحداث\n  Future<void> _selectStartDate() async {\n    final date = await showDatePicker(\n      context: context,\n      initialDate: _startDate ?? DateTime.now().subtract(const Duration(days: 30)),\n      firstDate: DateTime(2020),\n      lastDate: DateTime.now(),\n    );\n    if (date != null) {\n      setState(() {\n        _startDate = date;\n        _loadFiles();\n      });\n    }\n  }\n\n  Future<void> _selectEndDate() async {\n    final date = await showDatePicker(\n      context: context,\n      initialDate: _endDate ?? DateTime.now(),\n      firstDate: _startDate ?? DateTime(2020),\n      lastDate: DateTime.now(),\n    );\n    if (date != null) {\n      setState(() {\n        _endDate = date;\n        _loadFiles();\n      });\n    }\n  }\n\n  void _handleFileAction(String action, FileInfo file) async {\n    switch (action) {\n      case 'open':\n        // فتح الملف\n        ScaffoldMessenger.of(context).showSnackBar(\n          const SnackBar(content: Text('قريباً: فتح الملف')),\n        );\n        break;\n      case 'share':\n        // مشاركة الملف\n        ScaffoldMessenger.of(context).showSnackBar(\n          const SnackBar(content: Text('قريباً: مشاركة الملف')),\n        );\n        break;\n      case 'rename':\n        // إعادة تسمية\n        _showRenameDialog(file);\n        break;\n      case 'delete':\n        // حذف الملف\n        _showDeleteDialog(file);\n        break;\n    }\n  }\n\n  void _showRenameDialog(FileInfo file) {\n    final controller = TextEditingController(text: file.displayName);\n    showDialog(\n      context: context,\n      builder: (context) => AlertDialog(\n        title: const Text('إعادة تسمية الملف'),\n        content: TextField(\n          controller: controller,\n          decoration: const InputDecoration(\n            labelText: 'اسم الملف الجديد',\n          ),\n        ),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.pop(context),\n            child: const Text('إلغاء'),\n          ),\n          FilledButton(\n            onPressed: () {\n              // TODO: تنفيذ إعادة التسمية\n              Navigator.pop(context);\n              ScaffoldMessenger.of(context).showSnackBar(\n                const SnackBar(content: Text('تم تغيير اسم الملف')),\n              );\n            },\n            child: const Text('حفظ'),\n          ),\n        ],\n      ),\n    );\n  }\n\n  void _showDeleteDialog(FileInfo file) {\n    showDialog(\n      context: context,\n      builder: (context) => AlertDialog(\n        title: const Text('تأكيد الحذف'),\n        content: Text('هل تريد حذف ملف \"${file.displayName}\"؟'),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.pop(context),\n            child: const Text('إلغاء'),\n          ),\n          FilledButton(\n            onPressed: () async {\n              try {\n                await file.file.delete();\n                Navigator.pop(context);\n                ScaffoldMessenger.of(context).showSnackBar(\n                  const SnackBar(content: Text('تم حذف الملف')),\n                );\n                _loadFiles();\n              } catch (e) {\n                Navigator.pop(context);\n                ScaffoldMessenger.of(context).showSnackBar(\n                  SnackBar(content: Text('خطأ في حذف الملف: $e')),\n                );\n              }\n            },\n            child: const Text('حذف'),\n          ),\n        ],\n      ),\n    );\n  }\n\n  void _showCleanupDialog() {\n    showDialog(\n      context: context,\n      builder: (context) => AlertDialog(\n        title: const Text('تنظيف الملفات'),\n        content: const Text(\n          'هل تريد حذف الملفات الأقدم من 30 يوماً؟\\n\\nهذا الإجراء لا يمكن التراجع عنه.',\n        ),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.pop(context),\n            child: const Text('إلغاء'),\n          ),\n          FilledButton(\n            onPressed: () async {\n              Navigator.pop(context);\n              // TODO: تنفيذ تنظيف الملفات القديمة\n              ScaffoldMessenger.of(context).showSnackBar(\n                const SnackBar(content: Text('قريباً: تنظيف الملفات القديمة')),\n              );\n            },\n            child: const Text('تنظيف'),\n          ),\n        ],\n      ),\n    );\n  }\n\n  void _showStorageInfo() async {\n    final documentsDir = await getApplicationDocumentsDirectory();\n    showDialog(\n      context: context,\n      builder: (context) => AlertDialog(\n        title: const Text('معلومات التخزين'),\n        content: Column(\n          mainAxisSize: MainAxisSize.min,\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            Text('مسار التخزين:\\n${documentsDir.path}/NUM'),\n            const SizedBox(height: 16),\n            Text('إجمالي الملفات: ${_allFiles.length}'),\n            Text('الملفات المفلترة: ${_filteredFiles.length}'),\n            // TODO: إضافة معلومات أكثر عن التخزين\n          ],\n        ),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.pop(context),\n            child: const Text('إغلاق'),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _StatCard extends StatelessWidget {\n  const _StatCard({\n    required this.title,\n    required this.value,\n    required this.icon,\n    required this.color,\n  });\n\n  final String title;\n  final String value;\n  final IconData icon;\n  final Color color;\n\n  @override\n  Widget build(BuildContext context) {\n    return Card(\n      child: Padding(\n        padding: const EdgeInsets.all(12),\n        child: Column(\n          children: [\n            Icon(icon, color: color, size: 24),\n            const SizedBox(height: 8),\n            Text(\n              title,\n              style: const TextStyle(fontSize: 12, color: Colors.grey),\n              textAlign: TextAlign.center,\n            ),\n            Text(\n              value,\n              style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold),\n              textAlign: TextAlign.center,\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}"